//! Code generated by `TrivialType` derive must not depend on the prelude, which is not available
//! in modules with `#[no_implicit_prelude]`

#[no_implicit_prelude]
mod no_implicit_prelude {
    use ::ab_io_type::trivial_type::TrivialType;
    use ::core::clone::Clone;
    use ::core::marker::Copy;

    #[derive(Copy, Clone, TrivialType)]
    #[repr(C)]
    struct Struct {
        a: u8,
        b: [u8; 3],
    }

    #[derive(Copy, Clone, TrivialType)]
    #[repr(transparent)]
    struct TupleStruct(u32);

    #[derive(Copy, Clone, TrivialType)]
    #[repr(u8)]
    enum Enum {
        A { a: u8 },
        B { b: u8 },
    }
}

fn main() {}
